import { createAction, props } from '@ngrx/store';
import { LoginAction, LoginErrorState, RegisterAction } from '@store/model/auth.model';
import { LoginResponse, LogoutResponse, RegisterResponse } from '@model/network/auth/auth.model';

export const login = createAction(
	'[Auth] Login requested by user',
	props<LoginAction>()
);

export const loginSuccess = createAction(
	'[Auth] Login requested by user was successful',
	props<LoginResponse>()
);

export const loginError = createAction(
	'[Auth] Login requested by user got an error',
	props<LoginErrorState>()
);

export const register = createAction(
	'[Auth] Register requested by user',
	props<RegisterAction>()
);

export const registerSuccess = createAction(
	'[Auth] Register requested by user was successful',
	props<RegisterResponse>()
);

export const registerError = createAction(
	'[Auth] Register requested by user got an error',
	props<RegisterResponse | Error>()
);

export const logout = createAction(
	'[Auth] Logout requested by user'
);

export const logoutSuccess = createAction(
	'[Auth] Logout requested by user was successful',
	props<LogoutResponse>()
);

export const logoutError = createAction(
	'[Auth] Logout requested by user got an error',
	props<LogoutResponse | Error>()
);

export const getUserSession = createAction(
	'[Auth] Get user session requested by user'
);

export const getUserSessionSuccess = createAction(
	'[Auth] Get user session requested by user was successful',
	props<LoginResponse>()
);

export const getUserSessionError = createAction(
	'[Auth] Get user session requested by user got an error',
	props<LoginResponse | Error>()
);

export const firstTimeInit = createAction(
	'[Auth] First time init prompted',
	props<LoginAction>()
);

export const firstTimeInitSuccess = createAction(
	'[Auth] First time init prompted was successful',
	props<LoginResponse>()
);

export const firstTimeInitError = createAction(
	'[Auth] First time init prompted got an error',
	props<LoginResponse | Error>()
);