import { computed, ElementRef, inject, Signal } from '@angular/core';
import { kebabCase } from 'lodash-es';

export abstract class AbstractComponent {

	private readonly elementRef: ElementRef = inject(ElementRef);
	protected readonly tagName: Signal<string> = computed(() => this.elementRef.nativeElement.tagName);

	getId(idSuffix: string) {
		return kebabCase(`${this.tagName}-${idSuffix}`);
	}

}
