import { ApplicationConfig, enableProdMode, isDevMode, provideBrowserGlobalErrorListeners, provideZoneChangeDetection } from '@angular/core';
import { environment } from '@env/environment';
import '@extensions/global.extensions';
import { bootstrapApplication } from '@angular/platform-browser';
import { AppComponent } from '@app/app.component';
import { provideRouter, withHashLocation, withRouterConfig } from '@angular/router';
import { provideStoreDevtools } from '@ngrx/store-devtools';
import { provideToastr } from 'ngx-toastr';
import { ToastConfig } from '@shared/interfaces/notification.constants';
import { provideHttpClient, withInterceptorsFromDi } from '@angular/common/http';
import { ROUTES } from '@app/routes';
import { provideStore } from '@ngrx/store';
import { STORE_REDUCERS } from '@store/reducers/reducers';
import { provideEffects } from '@ngrx/effects';
import { STORE_EFFECTS } from '@store/effects/effects';
import 'zone.js';
import { provideMatFormFieldOptions } from '@app/material.module';
import { provideAnimations } from '@angular/platform-browser/animations';

if (environment.production) {
	enableProdMode();
}

// noinspection JSDeprecatedSymbols
const appConfig: ApplicationConfig = {
	providers: [
		provideBrowserGlobalErrorListeners(),
		provideZoneChangeDetection({ eventCoalescing: true }),
		provideRouter(ROUTES,
			// withDebugTracing(),
			withHashLocation(),
			withRouterConfig({
				onSameUrlNavigation: 'ignore'
			})
		),
		provideHttpClient(withInterceptorsFromDi()),
		provideEffects(STORE_EFFECTS),
		provideStore(STORE_REDUCERS),
		provideAnimations(), // Remove once possible. Required by ngx-toaster
		provideStoreDevtools({
			name: 'My App NgRX Devtools',
			maxAge: 25, // Retains last 25 states
			logOnly: environment.production ?? !isDevMode(), // Restrict extension to log-only mode
			autoPause: true, // Pauses recording actions and state changes when the extension window is not open
			trace: false, //  If set to true, will include stack trace for every dispatched action, so you can see it in trace tab jumping directly to that part of code
			traceLimit: 75, // maximum stack trace frames to be stored (in case trace option was provided as true)
			connectInZone: true // If set to true, the connection is established within the Angular zone
		}),
		provideToastr(ToastConfig),
		provideMatFormFieldOptions(),
	],
};

bootstrapApplication(AppComponent, appConfig).catch(e => console.error(e));
