export enum Permission {
	DINNER = 'DINNER',
	PARTY = 'PARTY',
	WEDDING = 'WEDDING',

	// Permission that can hide items for authenticated users with no specific permissions
	HIDDEN = 'HIDDEN',
}

export function hasPermission(userPermissions: Permission[], anyOf: (Permission | string)[]): boolean {
	return !!userPermissions?.find(userPermission => anyOf.includes(userPermission));
}
