import { Component, Input } from '@angular/core';
import { FormControl } from '@angular/forms';
import { ValidationService } from '../../service/validation.service';
import { AbstractComponent } from '@shared/component/abstract-component/abstract-component';

import { SharedImplementationModule } from '@shared/shared-implementation.module';


@Component({
	selector: 'app-control-messages',
	templateUrl: './control-messages.component.html',
	styleUrls: ['./control-messages.component.scss'],
	imports: [SharedImplementationModule]
})
export class ControlMessagesComponent extends AbstractComponent {
	@Input()
	public control!: FormControl;
	@Input()
	public labelName?: string;

	get errorMessage(): string | undefined {
		for (const propertyName in this.control?.errors) {
			if (this.control.errors.hasOwnProperty(propertyName) && this.control.touched) {
				return ValidationService.getValidationErrorMessage(this.control.errors[propertyName]);
			}
		}

		return undefined;
	}
}
