import { Component, computed, input, InputSignal, Signal, signal, WritableSignal } from '@angular/core';
import { SharedImplementationModule } from '@shared/shared-implementation.module';
import { Icon } from '@shared/constants/icons.constants';
import { IconComponent } from '@shared/component/icon/icon.component';
import { NgbTooltip } from '@ng-bootstrap/ng-bootstrap';

@Component({
  selector: 'app-copy-content',
	imports: [SharedImplementationModule, IconComponent, NgbTooltip],
  templateUrl: './copy-content.component.html',
  styleUrl: './copy-content.component.scss'
})
export class CopyContentComponent {

	text: InputSignal<string> = input.required();
	textToCopy: InputSignal<(originalValue: string) => string> = input((_) => this.text());
	tooltipText: InputSignal<string | null> = input(null);
	onClickTooltipText: InputSignal<string | null> = input(null);
	onClickTooltipCloseDelayMs: InputSignal<number> = input(2500);
	showSymbol: InputSignal<boolean> = input(true);

	protected readonly Icon = Icon;
	protected readonly lastTimeout: WritableSignal<NodeJS.Timeout | null> = signal(null);
	protected readonly hasActiveCopyTooltip: Signal<boolean> = computed(() => !!this.lastTimeout());

	onClick(wrapperRef: NgbTooltip, hoverRef: NgbTooltip): void {
		clearTimeout(this.lastTimeout());
		this.lastTimeout.set(this.closeTooltipWithDelay(wrapperRef));
		wrapperRef.open();
		hoverRef?.close();

		const fn = this.textToCopy();
		navigator.clipboard.writeText(fn(this.text())).then(() => {

		}).catch(error => {
			console.error(error);
		});
	}

	onClosed(): void {
		this.lastTimeout.set(null);
	}

	closeTooltipWithDelay(ref: NgbTooltip, delayMs: number = this.onClickTooltipCloseDelayMs()): NodeJS.Timeout {
		return setTimeout(() => {
			ref?.close(true);
		}, delayMs);
	}

}
