import { Component } from '@angular/core';
import { PagesModule } from '@pages/pages.module';
import { AbstractComponent } from '@shared/component/abstract-component/abstract-component';
import { Icon } from '@shared/constants/icons.constants';

@Component({
  selector: 'app-information',
  templateUrl: './information.component.html',
  styleUrls: ['./information.component.scss'],
	imports: [PagesModule]
})
export class InformationComponent extends AbstractComponent {

	protected readonly Icon = Icon;

	protected phoneNumber(value: string): string {
		return value.replaceAll(/[ -]/g, '');
	}

	protected swishMessage(value: string): string {
		return value.replaceAll(/[”"']/g, '') + ' - <NAMN>';
	}


}
