import { Component, input, InputSignal, OnDestroy, OnInit, signal, WritableSignal } from '@angular/core';
import { SharedImplementationModule } from '@shared/shared-implementation.module';
import { Subject, takeUntil, timer } from 'rxjs';

@Component({
  selector: 'app-countdown',
	imports: [SharedImplementationModule],
  templateUrl: './countdown.component.html',
  styleUrl: './countdown.component.scss'
})
export class CountdownComponent implements OnInit, OnDestroy {

	protected stopSubscription$: Subject<boolean> = new Subject<boolean>();

	date: InputSignal<Date> = input.required();
	tickMs: InputSignal<number> = input(1000);
	fadeBackground: InputSignal<boolean> = input(false);

	protected isReached: WritableSignal<boolean | null> = signal(null);
	protected days: WritableSignal<number | null> = signal(null);
	protected hours: WritableSignal<number | null> = signal(null);
	protected minutes: WritableSignal<number | null> = signal(null);
	protected seconds: WritableSignal<number | null> = signal(null);

	ngOnInit() {
		timer(0, this.tickMs())
			.pipe(takeUntil(this.stopSubscription$))
			.subscribe(() => {
				const futureDateInMs = this.date().getTime()
				if (isNaN(futureDateInMs)) {
					return;
				}

				const currentDateInMs = Date.now();
				const diff = futureDateInMs - currentDateInMs
				if (diff < 0) {
					this.isReached.set(true);
					return;
				} else {
					this.isReached.set(false);
				}

				const seconds = diff / 1000;
				const minutes = (diff / 1000) / 60;
				const hours = minutes / 60;
				const days = hours / 24;

				this.days.set(Math.floor(days));
				this.hours.set(Math.floor(hours % 24));
				this.minutes.set(Math.floor(minutes % 60));
				this.seconds.set(Math.floor(seconds % 60));
			});
	}

	ngOnDestroy(): void {
		this.stopSubscription$.next(true);
		this.stopSubscription$.complete();
	}

}
