import { ApiResponse, ExecutionStatus } from '@core/model/network/response.model';
import { AuthStatus } from '@core/model/network/auth/auth.model';


const VALID_STATUSES = [AuthStatus.VALID_AUTH, ExecutionStatus.SUCCESS]

export function getErrorMessageFromResponseBody<T extends ApiResponse>(response: T): string | null {
	if (response?.message) {
		return response.message;
	}

	return null;
}

// TODO: Check if 'T' generic can be used. Currently it's converted to another observable type despite having the 'any' return type
/**
 * Verifies the response body has a successful status code attached to it.
 * If not, an error is thrown.
 * @param response The response body to inspect
 */
export function verifyResponseBodyStatus<T extends ApiResponse>(response: any): any {
	response = response as T;
	if (!VALID_STATUSES.includes(response?.status)) {
		const errorMessage: string | null = getErrorMessageFromResponseBody(response);
		if (errorMessage) {
			throw new ApiError(response, errorMessage);
		}

		throw new ApiError(response, `Invalid response body status: [${response?.status}]`);
	}
	return response;
}

export class ApiError extends Error implements ApiResponse {

	constructor(apiResponse: ApiResponse, public readonly fallbackMessage?: string) {
		super(apiResponse?.message ?? fallbackMessage);
		Object.entries(apiResponse ?? {}).forEach(([key, value]) => {
			this[key] = value;
		});

	}

}