import { Injectable } from '@angular/core';
import { ToastrService } from 'ngx-toastr';
import { NotificationMessage, NotificationType } from '@shared/interfaces/notification.constants';
import { Subject } from 'rxjs';
import { IndividualConfig } from 'ngx-toastr/toastr/toastr-config';


// TODO: Implement history for notifications? Something the user can see even when they're closed? Currently an icon exists in the topbar

@Injectable({
	providedIn: 'root'
})
export class NotificationService {

	private notificationSubject: Subject<NotificationMessage> = new Subject<NotificationMessage>();

	private getToastConfig(message: string): Partial<IndividualConfig> {
		return {
			toastClass: 'ngx-toastr',
			positionClass: window.innerWidth > (80*16) ? 'toast-top-right' : 'toast-top-center',
			timeOut: 1500 + ((message?.length || 0) * 10)
		}
	}

	constructor(private toastService: ToastrService) {
		this.notificationSubject.subscribe({
			next: (notification) => {
				const config: Partial<IndividualConfig> = this.getToastConfig(notification.message);

				switch (notification.type) {
					case NotificationType.SUCCESS:
						this.toastService.success(notification.message, notification.title, config);
						break;
					case NotificationType.ERROR:
						this.toastService.error(notification.message, notification.title, config);
						break;
					case NotificationType.INFO:
						this.toastService.info(notification.message, notification.title, config);
						break;
					case NotificationType.WARNING:
						this.toastService.warning(notification.message, notification.title, config);
						break;
				}
			},
			error: (error: any) => {
				console.error('Toast could not be created', error);
			}
		});
	}

	toast(message: NotificationMessage): void {
		this.notificationSubject.next(message);
	}

}
