import { AuthState, RootState } from '@store/model/app.model';
import { Action, createReducer, on } from '@ngrx/store';
import { fromAuthActions } from '@store/actions/actions';
import { LoginResponse, UserSessionResponse } from '@model/network/auth/auth.model';
import { CommonUtil } from '@core/util';
import { LoginErrorState } from '@store/model/auth.model';


export const AUTH_INITIAL_STATE: AuthState = {

};

const reducers = createReducer(
	AUTH_INITIAL_STATE,
	on(fromAuthActions.loginSuccess, fromAuthActions.getUserSessionSuccess, (state: AuthState, newState: LoginResponse | UserSessionResponse) => {
		return CommonUtil.mergeToCopy(state, {
			userSession: {
				token: newState?.token,
				validUntil: newState?.validUntil,
				permissions: newState?.permissions ?? [],
				user: {
					username: newState?.user?.username,
					email: newState?.user?.email,
					firstName: newState?.user?.firstName,
					lastName: newState?.user?.lastName
				}
			}
		});
	}),
	on(fromAuthActions.logoutSuccess, fromAuthActions.logoutError, fromAuthActions.getUserSessionError, (state: AuthState) => {
		return CommonUtil.mergeToCopy(state, {
			userSession: undefined
		});
	}),
	on(fromAuthActions.loginError, (state: AuthState, newState: LoginErrorState) => {
		return CommonUtil.mergeToCopy(state, {
			userSession: undefined,
			loginErrorResponse: newState
		});
	})
);

export function authReducer(state: AuthState, action: Action) {
	return reducers(state, action);
}
