String.prototype.removePrefix = function (prefix: string): string {
	const hasPrefix = this.indexOf(prefix) === 0;
	return hasPrefix ? this.slice(prefix.length) : this.toString();
};

String.prototype.removeSuffix = function (suffix: string): string {
	const hasSuffix = this.endsWith(suffix);
	return hasSuffix ? this.slice(0, this.length - suffix.length) : this.toString();
};

String.prototype.padZeroes = function (length: number): string {
	let str: string = String(this);
	while (str.length < length) {
		str = '0' + str;
	}
	return str;
};

String.prototype.capitalize = function (): string {
	return (this && this.length > 0) ? this.charAt(0).toUpperCase() + (this.length > 1 ? this.slice(1) : '') : this as string;
};
