import { Injectable } from "@angular/core";
import { ActivatedRouteSnapshot, CanActivate, Router, RouterStateSnapshot } from "@angular/router";
import { Route } from "@shared/constants/routing-paths.constants";
import { AuthService } from "@core/service/auth.service";
import { Logger } from "@core/service/logger.service";
import { environment } from '@env/environment';


@Injectable({
	providedIn: 'root'
})
export class AuthGuard implements CanActivate {
	constructor(private readonly router: Router, private readonly authService: AuthService) {
	}

	canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
		if (this.authService.isAuthenticated()) {
			Logger.logGuard(AuthGuard.name, "Authenticated. Continuing to route");
			return true;
		}

		if (this.isCurrentlyOnLoginUrl(state.url)) {
			return true;
		}

		// Not logged in. Redirect to login page with the return url
		Logger.logGuard(AuthGuard.name, "Unauthenticated. Redirecting to login page");
		this.router.navigate([Route.LOGIN], { state: { returnUrl: state.url } });
		return false;
	}

	isCurrentlyOnLoginUrl(currentUrl: string) {
		return currentUrl.startsWith(Route.LOGIN);
	}

}
