import { ThemeProvider, Themes, ThemeValue } from '@model/common/theme.model';

export const ThemeIcon: ThemeProvider<string> = Object.entries(Themes).reduce((newObj, [key, val]) => {
	newObj[key] = val.icon;
	return newObj;
}, {} as ThemeProvider<string>);

export interface ToolbarStorage {
	currentTheme?: ThemeValue;
}

