import { Injectable } from '@angular/core';
import { HttpErrorResponse, HttpEvent, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { Observable, retry, throwError, timer } from 'rxjs';
import { Router } from '@angular/router';
import { catchError } from 'rxjs/operators';
import { Route } from '@shared/constants/routing-paths.constants';
import { NotificationService } from '@core/service/notification.service';
import { NotificationType } from '@shared/interfaces/notification.constants';
import { Logger } from '@core/service/logger.service';
import { AuthService } from '@core/service/auth.service';


// noinspection JSMethodCanBeStatic
@Injectable()
export class ErrorInterceptor implements HttpInterceptor {
	private static readonly RETRY_DELAY_MS: number = 1000;
	private static readonly RETRY_MAX_ATTEMPTS: number = 3; // Excluding the first request

	constructor(private router: Router, private notificationService: NotificationService, private authService: AuthService) {
	}

	private isOnAuthPage(requestUrl: string): boolean {
		return requestUrl.includes(Route.LOGIN)
			|| requestUrl.includes(Route.REGISTER)
			|| requestUrl.includes(Route.LOGOUT);
	}

	intercept(request: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
		return next.handle(request).pipe(
			this.retryRequestIfPossible(),
			catchError(error => {
				if (error instanceof HttpErrorResponse) {
					if (error.error instanceof ErrorEvent) {
						Logger.logGuard(ErrorInterceptor.name, 'Error Event');
					} else if (!this.isOnAuthPage(request.url)) {
						Logger.logGuard(ErrorInterceptor.name, `Error status : ${error.status} ${error.statusText}`);
						switch (error.status) {
							case 401:
								this.notificationService.toast({
									title: 'Inloggning saknas',
									message: 'Antingen så har inloggningssessionen upphört eller så är du inte inloggad',
									type: NotificationType.ERROR
								});
								this.router.navigate([Route.LOGIN]);
								break;
							case 403:
								this.notificationService.toast({
									title: 'Förbjudet',
									message: 'Du har inte åtkomst till denna resurs',
									type: NotificationType.ERROR
								});
								break;
						}
					}
				} else {
					Logger.logGuard(ErrorInterceptor.name, 'Wtf is this shit...?');
				}
				return throwError(() => error);
			})
		);
	}

	isRetryableError(error: any): boolean {
		if (error instanceof HttpErrorResponse) {
			const notRetryableCodes: number[] = [400, 401, 403, 418, 304];
			return !notRetryableCodes.includes(error?.status);
		}

		return true;
	}

	retryRequestIfPossible(): any {
		return retry({
			count: ErrorInterceptor.RETRY_MAX_ATTEMPTS,
			delay: (error: any, retryCount: number) => {
				if (this.isRetryableError(error)) {
					Logger.logInterceptor(`Retrying request towards [${error.url}]. Retry ${retryCount}/${ErrorInterceptor.RETRY_MAX_ATTEMPTS}`);
					return timer(ErrorInterceptor.RETRY_DELAY_MS * Math.max(retryCount, 1));
				}

				return throwError(() => error);
			}
		});
	}

}
