import { createFeatureSelector, createSelector } from '@ngrx/store';
import { AuthState } from '@store/model/app.model';

export const selectAuth = createFeatureSelector<AuthState>('auth');

export const selectUserSession = createSelector(
	selectAuth,
	(state: AuthState) => state?.userSession
);

export const selectLoginResponseError = createSelector(
	selectAuth,
	(state: AuthState) => state?.loginErrorResponse
);
