import { Injectable } from '@angular/core';
import { AuthService } from '@core/service/auth.service';
import { map, of, switchMap } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { fromAuthActions } from '@store/actions/actions';
import { Actions, createEffect, ofType } from '@ngrx/effects';
import { NotificationService } from '@core/service/notification.service';
import { NotificationType } from '@shared/interfaces/notification.constants';
import { Router } from '@angular/router';
import { Route } from '@shared/constants/routing-paths.constants';
import { logoutSuccess } from '@store/actions/auth.actions';
import { LoginAction, RegisterAction } from '@store/model/auth.model';
import { Logger } from '@core/service/logger.service';
import { LoginResponse, LogoutResponse, RegisterResponse, UserSessionResponse } from '@model/network/auth/auth.model';

@Injectable()
export class AuthEffects {

	constructor(private actions$: Actions,
							private authService: AuthService,
							private notificationService: NotificationService,
							private router: Router) {
	}

	login$ = createEffect(() =>
		this.actions$.pipe(
			ofType(fromAuthActions.login),
			switchMap((action: LoginAction) => this.authService.login(action.request).pipe(
				map((response: LoginResponse) => {
					this.authService.setUserTokenFromLocalStorage(response.token);
					this.authService.setRememberSession(action.request.rememberMe ?? false);
					this.router.navigate([action.redirectUrl || Route.HOME]);
					// this.notificationService.toast({
					// 	title: 'Inloggning lyckades',
					// 	message: 'Du har blivit inloggad på hemsidan',
					// 	type: NotificationType.SUCCESS
					// });
					return fromAuthActions.loginSuccess(response)
				}),
				catchError((error) => {
					console.log(error);
					this.authService.removeUserSessionLocally();
					Logger.logStoreEffects(AuthEffects.name, 'Error for login$:', error);
					// this.notificationService.toast({
					// 	title: 'Inloggning misslyckades',
					// 	message: error?.message || "Något gick fel",
					// 	type: NotificationType.ERROR
					// });
					return of(fromAuthActions.loginError({ ...error, message: error.message ?? 'Något gick fel med inloggningen' }));
				})
			))
		));

	register$ = createEffect(() =>
		this.actions$.pipe(
			ofType(fromAuthActions.register),
			switchMap((action: RegisterAction) => this.authService.register(action.request).pipe(
				map((response: RegisterResponse) => {
					this.router.navigate([Route.LOGIN], { state: { returnUrl: action?.redirectUrl } })
					this.notificationService.toast({
						title: 'Registration successful',
						message: 'You have successfully registered a user. Please login',
						type: NotificationType.SUCCESS
					});
					return fromAuthActions.registerSuccess(response)
				}),
				catchError((error) => {
					Logger.logStoreEffects(AuthEffects.name, 'Error for register$:', error);
					this.notificationService.toast({
						title: 'Registration failed',
						message: error?.message || "User could not registered",
						type: NotificationType.ERROR
					});
					return of(fromAuthActions.registerError(error))
				})
			))
		));

	logout$ = createEffect(() =>
		this.actions$.pipe(
			ofType(fromAuthActions.logout),
			switchMap(() => this.authService.logout({ token: this.authService.getSessionToken() }).pipe(
				map((response: LogoutResponse) => {
					this.router.navigate([Route.LOGIN])
					// this.notificationService.toast({
					// 	title: 'Utloggning lyckades',
					// 	message: 'Du är nu utloggad från hemsidan',
					// 	type: NotificationType.SUCCESS
					// });
					return logoutSuccess(response)
				}),
				catchError((error: LogoutResponse) => {
					this.notificationService.toast({
						title: 'Utloggning misslyckades',
						message: error?.message || "Något gick fel",
						type: NotificationType.ERROR
					});
					return of(fromAuthActions.logoutError);
				})
			))
		));

	getUserSession$ = createEffect(() =>
		this.actions$.pipe(
			ofType(fromAuthActions.getUserSession),
			switchMap(() => this.authService.getUserSession().pipe(
				map((response: UserSessionResponse) => {
					return fromAuthActions.getUserSessionSuccess(response);
				}),
				catchError((error) => {
					this.authService.removeUserSessionLocally();
					Logger.logStoreEffects(AuthEffects.name, 'Error for getUserSession$:', error);
					this.notificationService.toast({
						title: 'Misslyckades att hämta föregående inloggning',
						message: error?.message || "Vänligen logga in igen. Den förra sessionen har utgått",
						type: NotificationType.WARNING
					});
					return of(fromAuthActions.getUserSessionError(error))
				})
			))
		));

}