import { cloneDeep } from 'lodash-es';

export class CommonUtil {

	static isDefined(obj: any): boolean {
		return obj !== undefined && obj !== null;
	}

	static equals(o1: any, o2: any): boolean {
		return JSON.stringify(o1) === JSON.stringify(o2);
	}

	static containsAnyEqual<T>(arr: T[], obj: T): boolean {
		return !!arr?.find(el => this.equals(el, obj));
	}

	static isObject(value: any): value is object {
		return typeof value === 'object' && !Array.isArray(value) && value !== null;
	}

	static isString(value: any): value is string {
		return typeof value === 'string';
	}

	static flattenObject(value: object): object {
		const flattenedObject: any = {};

		for (const [innerKey, innerValue] of Object.entries(value)) {
			if (typeof innerValue == "object" && !(innerValue instanceof Date) && !Array.isArray(innerValue) && !(innerValue instanceof RegExp)) {
				Object.assign(flattenedObject, CommonUtil.flattenObject(innerValue));
			} else {
				flattenedObject[innerKey] = innerValue;
			}
		}
		return flattenedObject
	}

	static deepClone<T>(value: T): T {
		return cloneDeep(value);
	}

	/**
	 * Merges two arrays, but only keeps one set of values according to the unique property fetched by a function.
	 * The last stored entries will be overriding the first ones if conflict happens
	 */
	static mergeToUniqueArrayByProperty<T>(array1: T[], array2OrObj: T | T[], propertyFn: (element: T) => any): T[] {
		if (!Array.isArray(array2OrObj)) {
			array2OrObj = [array2OrObj] as T[];
		}
		return [...new Map([...array1, ...array2OrObj].map(item => [propertyFn(item), item])).values()];
	}

	static getEnumByValue<T>(enumType: T, value: any): T | null {
		return Object.values(enumType).includes(value) ? value as T : null;
	}

	static mergeToCopy<T extends object>(original: T, ...valuesToMerge: Partial<T>[]): T {
		return this.mergeInPlace(this.deepClone(original), ...valuesToMerge.map((value: Partial<T>) => this.deepClone(value))); // False-positive of 'TS2345'?
	}

	static mergeInPlace<T extends object>(original: T, ...valuesToMerge: Partial<T>[]): T {
		valuesToMerge?.forEach(valueToMerge => this.mergeInPlaceHelper(original, valueToMerge));
		return original;
	}

	private static mergeInPlaceHelper<T extends { [index: string]: any }>(original: T, valueToMerge: Partial<T>): T {
		if (original && valueToMerge) {
			Object.keys(valueToMerge).forEach((key: string) => {
				if (this.isObject(valueToMerge[key])) {
					if (!original[key]) {
						Object.assign(original, { [key]: {} });
					}
					this.mergeInPlaceHelper(original[key], valueToMerge[key]);
				} else {
					// Because `original[key] = valueToMerge[key];` produces a typescript error, even though it works... https://github.com/microsoft/TypeScript/issues/47357
					Reflect.set(original, key, valueToMerge[key]);
				}
			})
		}

		return original;
	}

	static getKeyByValue<T>(object: T, value: any): keyof T | null {
		return Object.keys(object).find(key => object[key] === value) as keyof T ?? null;
	}

}
